        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by improper handling of the D-Bus API message formatting, specifically the incorrect opening and closing of containers for properties such as `SystemCallFilter` and `RestrictAddressFamilies`. The previous implementation attempted to append values directly without utilizing the expected structure, leading to potential inconsistencies and errors in communication with the D-Bus interface.

        Commit message:
        core: fix D-Bus API

This fixes bugs introduced by cffaed83e87bde81378b2be74192193850d0e03a.

Closes #7129.  

        Patch:

 int bus_append_unit_property_assignment(sd_bus_message *m, const char *assignment) {
         const char *eq, *field;
         UnitDependency dep;
         int r, rl;

         assert(m);
         assert(assignment);

         eq = strchr(assignment, '=');
         if (!eq) {
                 log_error("Not an assignment: %s", assignment);
                 return -EINVAL;
         }

         r = sd_bus_message_open_container(m, SD_BUS_TYPE_STRUCT, "sv");
         if (r < 0)
                 return bus_log_create_error(r);

         field = strndupa(assignment, eq - assignment);
         eq++;

         if (streq(field, "CPUQuota")) {

                 if (isempty(eq))
                         r = sd_bus_message_append(m, "sv", "CPUQuotaPerSecUSec", "t", USEC_INFINITY);
                 else {
                         r = parse_percent_unbounded(eq);
                         if (r <= 0) {
                                 log_error_errno(r, "CPU quota '%s' invalid.", eq);
                                 return -EINVAL;
                         }

                         r = sd_bus_message_append(m, "sv", "CPUQuotaPerSecUSec", "t", (usec_t) r * USEC_PER_SEC / 100U);
                 }

                 goto finish;

         } else if (streq(field, "EnvironmentFile")) {

                 r = sd_bus_message_append(m, "sv", "EnvironmentFiles", "a(sb)", 1,
                                           eq[0] == '-' ? eq + 1 : eq,
                                           eq[0] == '-');
                 goto finish;

         } else if (STR_IN_SET(field, "AccuracySec", "RandomizedDelaySec", "RuntimeMaxSec")) {
                 char *n;
                 usec_t t;
                 size_t l;

                 r = parse_sec(eq, &t);
                 if (r < 0)
                         return log_error_errno(r, "Failed to parse %s= parameter: %s", field, eq);

                 l = strlen(field);
